<?php $pageTitle='Admin overview'; require __DIR__.'/../partials/header.php'; ?><main id="main" class="shell"><header class="page-heading"><p class="eyebrow">NepalStay administration</p><h1>A clear view of your stays.</h1><p>A current snapshot of reservations recorded in your booking system.</p></header><div class="account-layout"><?php require __DIR__.'/../partials/account-nav.php'; ?><section class="account-content"><div class="admin-stats"><?php foreach(['total'=>'Total reservations','pending'=>'Awaiting confirmation','confirmed'=>'Confirmed reservations'] as $key=>$label): ?><div class="stat-card"><span class="label"><?= $label ?></span><strong><?= (int)($overview[$key] ?? 0) ?></strong><small>All recorded dates</small></div><?php endforeach; ?></div><div class="surface"><div class="surface-title"><h2>Recent reservations</h2><?= ns_icon('calendar') ?></div><?php if(empty($recentBookings)): ?><div class="empty-state"><h3>No reservations yet.</h3><p>New reservations will appear here.</p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Reservation</th><th>Guest</th><th>Stay</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($recentBookings as $booking): ?><tr><td>#<?= (int)$booking['id'] ?><small><?= ns_e($booking['room_title']) ?></small></td><td><?= ns_e($booking['guest_name']) ?><small><?= (int)$booking['num_guests'] ?> guests</small></td><td><?= ns_e(ns_date($booking['check_in'])) ?><small>to <?= ns_e(ns_date($booking['check_out'])) ?></small></td><td>NPR <?= ns_money($booking['total_price']) ?></td><td><span class="status <?= ns_status($booking['status']) ?>"><?= ns_e(ucfirst($booking['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section></div></main><?php require __DIR__.'/../partials/footer.php'; ?>